"""Deterministic observations only; no DevForgeAI state or acceptance authority."""

import hashlib
import json
import re
import stat
from pathlib import Path, PurePosixPath
from urllib.parse import unquote, urlsplit

VERSION = "1.0.0"
GRADER_IDS = ("package_links", "manifest_accounting")
MAX_BYTES = 32 * 1024 * 1024
MAX_FILES = 2000


def digest(data):
    return hashlib.sha256(data).hexdigest()


def strict_json(text):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError("duplicate JSON key: " + key)
            result[key] = value
        return result

    def constant(value):
        raise ValueError("non-finite JSON value: " + value)

    return json.loads(text, object_pairs_hook=pairs, parse_constant=constant)


def is_link(path):
    info = path.lstat()
    return stat.S_ISLNK(info.st_mode) or bool(
        getattr(info, "st_file_attributes", 0) & 0x400
    )


def bounded_path(root, relative, allow_dot=False):
    if not isinstance(relative, str) or not relative or "\\" in relative or ":" in relative:
        raise ValueError("expected a forward-slash relative path")
    parts = PurePosixPath(relative).parts
    if relative == "." and allow_dot:
        return root
    if not parts or any(p in ("..", ".") for p in relative.split("/")) or relative.startswith("/"):
        raise ValueError("unsafe relative path: " + relative)
    current = root
    for part in parts:
        if part.casefold() in ("backup", "backups"):
            raise ValueError("excluded backup boundary: " + relative)
        current = current / part
        if current.exists() or current.is_symlink():
            if is_link(current):
                raise ValueError("link/reparse boundary: " + relative)
    if not current.resolve().is_relative_to(root.resolve()):
        raise ValueError("path escapes root: " + relative)
    return current


def snapshot(root):
    if not root.is_dir() or is_link(root):
        raise ValueError("snapshot root must be a regular directory")
    files = {}
    total = 0

    def walk(directory):
        nonlocal total
        for item in sorted(directory.iterdir(), key=lambda p: p.name):
            rel = item.relative_to(root).as_posix()
            if item.name.casefold() in ("backup", "backups"):
                raise ValueError("excluded backup boundary: " + rel)
            if is_link(item):
                raise ValueError("link/reparse boundary: " + rel)
            if item.is_dir():
                walk(item)
            elif item.is_file():
                size = item.stat().st_size
                if len(files) >= MAX_FILES or total + size > MAX_BYTES:
                    raise ValueError("snapshot exceeds 2000 files or 32 MiB")
                data = item.read_bytes()
                total += len(data)
                if total > MAX_BYTES:
                    raise ValueError("snapshot exceeds 32 MiB")
                files[rel] = data
            else:
                raise ValueError("non-regular snapshot entry: " + rel)

    walk(root)
    return files


def result(problems, files):
    return {
        "status": "FAIL" if problems else "PASS",
        "observations": problems or ["No discrepancy in the measured properties."],
        "candidate_digests": {name: digest(data) for name, data in sorted(files.items())},
    }


def package_links(root, params):
    if set(params) != {"path"}:
        raise ValueError("package_links requires only path")
    folder = bounded_path(root, params["path"], allow_dot=True)
    files = snapshot(folder)
    problems = []
    if "SKILL.md" not in files:
        problems.append("Missing SKILL.md")
    for name, data in files.items():
        if not name.lower().endswith(".md"):
            continue
        content = data.decode("utf-8-sig")
        # This grader covers ordinary Markdown links, not HTML or code examples.
        content = re.sub(r"(?ms)^\s*(`{3,}|~{3,})[^\n]*\n.*?^\s*\1\s*$", "", content)
        content = re.sub(r"`[^`\n]*`", "", content)
        definitions = dict(re.findall(r"(?m)^\s*\[([^\]]+)\]:\s*<?([^\s>]+)>?", content))
        definitions = {key.casefold(): value for key, value in definitions.items()}
        links = re.findall(r"!?\[[^\]\n]*\]\(\s*(<[^>]+>|[^\s)]+)(?:\s+[^)]*)?\)", content)
        for label, reference in re.findall(r"!?\[([^\]\n]+)\]\[([^\]\n]*)\]", content):
            key = (reference or label).casefold()
            if key not in definitions:
                problems.append(name + ": undefined reference " + key)
            else:
                links.append(definitions[key])
        links.extend(definitions.values())
        for raw in links:
            url = urlsplit(raw.strip("<>"))
            if url.scheme in ("http", "https", "mailto") or (not url.path and not url.netloc):
                continue
            if url.scheme or url.netloc:
                problems.append(name + ": unsupported link " + raw)
                continue
            relative = unquote(url.path)
            if "\\" in relative or ":" in relative or relative.startswith("/"):
                problems.append(name + ": unsafe link " + raw)
                continue
            target = (folder / PurePosixPath(name).parent / relative).resolve()
            if not target.is_relative_to(folder.resolve()):
                problems.append(name + ": escaping link " + raw)
            elif target.relative_to(folder.resolve()).as_posix() not in files:
                problems.append(name + ": missing file link " + raw)
    prefix = "" if params["path"] == "." else params["path"] + "/"
    return result(problems, {prefix + key: value for key, value in files.items()})


def manifest_entries(value):
    if not isinstance(value, dict) or value.get("schema_version") != "1" or not isinstance(value.get("files"), list):
        raise ValueError("manifest requires schema_version 1 and files array")
    entries = {}
    for entry in value["files"]:
        name = entry["path"]
        if not isinstance(name, str) or name in entries:
            raise ValueError("invalid or duplicate manifest path")
        if type(entry["bytes"]) is not int or entry["bytes"] < 0:
            raise ValueError("invalid manifest byte count")
        if not isinstance(entry["sha256"], str) or not re.fullmatch(r"[0-9a-f]{64}", entry["sha256"]):
            raise ValueError("invalid manifest digest")
        entries[name] = (entry["bytes"], entry["sha256"])
    return entries


def manifest_accounting(root, params):
    if set(params) != {"source", "destination", "evidence"}:
        raise ValueError("manifest_accounting requires source, destination, evidence")
    folders = {key: bounded_path(root, value) for key, value in params.items()}
    resolved = list(folders.values())
    if any(a == b or a.is_relative_to(b) or b.is_relative_to(a) for i, a in enumerate(resolved) for b in resolved[i + 1:]):
        raise ValueError("source, destination and evidence must be disjoint")
    inventories = {key: snapshot(path) for key, path in folders.items()}
    evidence = inventories["evidence"]
    before = manifest_entries(strict_json(evidence["source-manifest.json"].decode("utf-8-sig")))
    destination = manifest_entries(strict_json(evidence["destination-manifest.json"].decode("utf-8-sig")))
    dispositions = strict_json(evidence["file-dispositions.json"].decode("utf-8-sig"))
    if not isinstance(dispositions, dict) or dispositions.get("schema_version") != "1" or not isinstance(dispositions.get("files"), list):
        raise ValueError("dispositions require schema_version 1 and files array")
    problems = []
    for key, expected in (("source", before), ("destination", destination)):
        actual = {name: (len(data), digest(data)) for name, data in inventories[key].items()}
        if actual != expected:
            problems.append(key + " bytes or file set differs from manifest")
    seen = set()
    for entry in dispositions["files"]:
        name = entry["source_path"]
        if name in seen or name not in before:
            problems.append("duplicate or unknown disposition: " + str(name))
            continue
        seen.add(name)
        if entry["source_sha256"] != before[name][1]:
            problems.append("disposition source digest mismatch: " + name)
        action, targets = entry["disposition"], entry["target_paths"]
        if action not in ("PRESERVE", "REWRITE", "CONSOLIDATE", "OMIT", "DEFER"):
            raise ValueError("unknown disposition")
        if not isinstance(targets, list) or any(not isinstance(t, str) for t in targets) or len(targets) != len(set(targets)):
            raise ValueError("target_paths must contain unique strings")
        if bool(targets) != (action not in ("OMIT", "DEFER")):
            problems.append("disposition target count mismatch: " + name)
        for target in targets:
            if target not in destination:
                problems.append("disposition target absent: " + target)
            elif action == "PRESERVE" and before[name] != destination[target]:
                problems.append("PRESERVE byte mismatch: " + name + " -> " + target)
    if seen != set(before):
        problems.append("source files missing dispositions")
    all_files = {params[key] + "/" + name: data for key, files in inventories.items() for name, data in files.items()}
    return result(problems, all_files)


def grade(grader_id, root, params):
    if not isinstance(params, dict):
        raise ValueError("grader params must be an object")
    if grader_id == "package_links":
        return package_links(root, params)
    if grader_id == "manifest_accounting":
        return manifest_accounting(root, params)
    raise ValueError("unknown grader: " + str(grader_id))
"""Emit bounded, deterministic JSONL observations. Never issue acceptance."""

import argparse
import hashlib
import importlib.util
import json
import platform
import re
import stat
import sys
from pathlib import Path

sys.dont_write_bytecode = True
GRADER_IDS = ("package_links", "manifest_accounting")
VERSION = "1.0.0"


def digest(data):
    return hashlib.sha256(data).hexdigest()


def is_link(path):
    info = path.lstat()
    return stat.S_ISLNK(info.st_mode) or bool(getattr(info, "st_file_attributes", 0) & 0x400)


def strict_json(text):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError("duplicate JSON key: " + key)
            result[key] = value
        return result

    def constant(value):
        raise ValueError("non-finite JSON value: " + value)

    return json.loads(text, object_pairs_hook=pairs, parse_constant=constant)

REQUIRED = {
    "SKILL.md", "scripts/run_evaluation.py", "scripts/graders.py",
    "references/evaluation.md", "evals/cases.jsonl", "evals/runtime.json",
    "evals/evidence.schema.json", "tests/test_evaluation.py",
    "evals/fixtures/portable/source/SKILL.md",
    "evals/fixtures/portable/destination/SKILL.md",
    "evals/fixtures/portable/evidence/source-manifest.json",
    "evals/fixtures/portable/evidence/destination-manifest.json",
    "evals/fixtures/portable/evidence/file-dispositions.json",
}


def package_binding(root):
    # Bootstrap with standard-library code before importing any grader bytes.
    files, total = {}, 0
    pending = [root]
    if not root.is_dir() or is_link(root):
        raise ValueError("package-root must be a regular directory")
    while pending:
        for item in sorted(pending.pop().iterdir()):
            if item.name.casefold() in ("backup", "backups") or is_link(item):
                raise ValueError("excluded package boundary: " + item.name)
            if item.is_dir():
                pending.append(item)
            elif item.is_file():
                if len(files) >= 2000 or total + item.stat().st_size > 32 * 1024 * 1024:
                    raise ValueError("package exceeds 2000 files or 32 MiB")
                data = item.read_bytes()
                total += len(data)
                if total > 32 * 1024 * 1024:
                    raise ValueError("package exceeds 32 MiB")
                files[item.relative_to(root).as_posix()] = data
            else:
                raise ValueError("non-regular package entry")
    manifest_bytes = files.pop("evals/build-manifest.json")
    manifest = strict_json(manifest_bytes.decode("utf-8-sig"))
    if not isinstance(manifest, dict) or manifest.get("schema_version") != "1" or manifest.get("graders") != {name: VERSION for name in GRADER_IDS}:
        raise ValueError("unsupported build manifest or grader versions")
    expected = manifest["artifacts"]
    actual = {name: digest(data) for name, data in files.items()}
    if not REQUIRED <= set(actual) or actual != expected:
        raise ValueError("required build artifact missing, unlisted or digest mismatch")
    if Path(__file__).resolve() != (root / "scripts/run_evaluation.py").resolve():
        raise ValueError("package-root must own the running runner")
    # Execute exactly the verified bytes, so a subsequent path edit cannot
    # replace the module between digest comparison and module loading.
    module_path = root / "scripts/graders.py"
    module = importlib.util.module_from_spec(importlib.util.spec_from_loader("bound_graders", loader=None))
    exec(compile(files["scripts/graders.py"], str(module_path), "exec"), module.__dict__)
    return digest(manifest_bytes), actual["scripts/graders.py"], module.grade


def load_cases(data):
    if len(data) > 1024 * 1024:
        raise ValueError("cases exceed 1 MiB")
    lines = data.decode("utf-8-sig").splitlines()
    if not lines or len(lines) > 1000:
        raise ValueError("cases require 1 to 1000 JSONL records")
    cases, seen = [], set()
    for line in lines:
        case = strict_json(line)
        if not isinstance(case, dict) or set(case) != {"case_id", "grader_id", "params", "expected"}:
            raise ValueError("case fields must be case_id, grader_id, params, expected")
        case_id = case["case_id"]
        if not isinstance(case_id, str) or not re.fullmatch(r"[a-zA-Z0-9_.-]{1,100}", case_id) or case_id in seen:
            raise ValueError("invalid or duplicate case_id")
        if case["grader_id"] not in GRADER_IDS or case["expected"] not in ("PASS", "FAIL") or not isinstance(case["params"], dict):
            raise ValueError("unknown grader or invalid expected/params")
        seen.add(case_id)
        cases.append(case)
    if set(case["grader_id"] for case in cases) != set(GRADER_IDS):
        raise ValueError("suite must exercise every required grader")
    return cases


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("package-root", "candidate-root", "cases", "output", "run-id"):
        parser.add_argument("--" + name, required=True)
    args = parser.parse_args(argv)
    output = Path(args.output).absolute()
    package = Path(args.package_root).absolute()
    candidate = Path(args.candidate_root).absolute()
    cases_path = Path(args.cases).absolute()
    base = {
        "schema_version": "1", "run_id": args.run_id,
        "python_version": platform.python_version(), "platform": platform.platform(),
        "case_id": None, "grader_id": None, "grader_version": VERSION,
        "grader_sha256": None, "build_manifest_sha256": None, "cases_sha256": None,
        "candidate_digests": {}, "observations": [], "status": "ERROR",
        "expected": None, "expectation_met": False, "error": None,
    }
    records = []
    safe_output = False
    code = 2
    try:
        if not re.fullmatch(r"[a-zA-Z0-9_.-]{1,100}", args.run_id):
            raise ValueError("invalid run-id")
        for path in (package, candidate, cases_path, output.parent):
            for part in [path, *path.parents]:
                if part.exists() and is_link(part):
                    raise ValueError("link/reparse input or output boundary")
        if not output.parent.is_dir() or output.exists() or output.is_symlink():
            raise ValueError("output requires an existing directory and a new file")
        if any(output.resolve().is_relative_to(root.resolve()) for root in (package, candidate)) or output.resolve() == cases_path.resolve():
            raise ValueError("output must be outside package/candidate and cannot overwrite cases")
        safe_output = True
        base["build_manifest_sha256"], base["grader_sha256"], grade = package_binding(package)
        if sys.version_info < (3, 10):
            raise ValueError("Python 3.10 or newer required")
        if cases_path.stat().st_size > 1024 * 1024:
            raise ValueError("cases exceed 1 MiB")
        case_data = cases_path.read_bytes()
        base["cases_sha256"] = digest(case_data)
        cases = load_cases(case_data)
        code = 0
        for case in cases:
            record = dict(base, case_id=case["case_id"], grader_id=case["grader_id"], expected=case["expected"])
            try:
                record.update(grade(case["grader_id"], candidate, case["params"]))
                record["expectation_met"] = record["status"] == case["expected"]
                if not record["expectation_met"]:
                    code = max(code, 1)
            except (ValueError, OSError, KeyError, TypeError, UnicodeError) as exc:
                record["error"] = type(exc).__name__ + ": " + str(exc)
                code = 2
            records.append(record)
    except (ValueError, OSError, KeyError, TypeError, UnicodeError) as exc:
        records = [dict(base, error=type(exc).__name__ + ": " + str(exc))]
    payload = "".join(json.dumps(record, sort_keys=True, allow_nan=False) + "\n" for record in records)
    if safe_output:
        try:
            with output.open("x", encoding="utf-8", newline="\n") as stream:
                stream.write(payload)
        except OSError as exc:
            print("Evidence output error: " + str(exc), file=sys.stderr)
            return 2
        print(json.dumps({"records": len(records), "exit_code": code, "output": str(output), "authority": "NONE"}))
    else:
        print(payload, end="", file=sys.stderr)
    return code


if __name__ == "__main__":
    sys.exit(main())
